#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace fedspatial; namespace fs=std::filesystem;
static Matrix load(const fs::path&p){std::ifstream f(p);int r,c;if(!(f>>r>>c))throw std::runtime_error("missing "+p.string());Matrix x(r,c);for(double&v:x.a)f>>v;return x;}
static WorkerInput w100(int n){auto a=load("sync_gpu/tests/fixtures/figure1_reference/worker_0.txt");Matrix s(n,2),z(n,1),x(n,5);for(int i=0;i<n;++i){s(i,0)=a(i,0);s(i,1)=a(i,1);z(i,0)=a(i,2);for(int j=0;j<5;++j)x(i,j)=a(i,j+3);}return{s,z,x};}
static bool check(const char*tag,const WorkerInput&w,const Matrix&k,const GlobalParameters&p,const Matrix&want,double tol){GpuContext c(0);(void)build_device_mu_sigma_local(c,w,k,p);const auto h0=c.raw_h2d_bytes(),d0=c.result_d2h_bytes(),combined0=c.b_derivative_allocation_count(),pair0=c.b_pair_derivative_allocation_count();const auto a=compute_device_delta_theta_theta_hessian_reduction_streamed(c,w,k,p);const auto h1=c.raw_h2d_bytes(),d1=c.result_d2h_bytes();const auto b=compute_device_delta_theta_theta_hessian_reduction_streamed(c,w,k,p);const double e=std::max({std::abs(a.hessian[0]-want(1,1)),std::abs(a.hessian[1]-want(1,2)),std::abs(a.hessian[2]-want(2,2))});double decomp=0.;for(int q=0;q<3;++q)decomp=std::max(decomp,std::abs(a.hessian[q]-(a.terms[q][0]+a.terms[q][1]+a.terms[q][2])));const bool repeat=std::memcmp(&a,&b,sizeof(a))==0,zero=c.raw_h2d_bytes()==h1;const double sym=std::abs(want(1,2)-want(2,1));std::cout<<tag<<" GOT=("<<a.hessian[0]<<','<<a.hessian[1]<<','<<a.hessian[2]<<") WANT=("<<want(1,1)<<','<<want(1,2)<<','<<want(2,2)<<") PYTHON_AUTOGRAD_MAX_ABS="<<e<<" DENSE_DECOMPOSITION_MAX_ABS="<<decomp<<" SYMMETRY_MAX_ABS="<<sym<<" EXACT_REPEAT="<<(repeat?"PASS":"FAIL")<<" ACTIVE_H2D_BYTES="<<h1-h0<<" ACTIVE_D2H_BYTES="<<d1-d0<<" COMBINED_B_ALLOCATIONS="<<c.b_derivative_allocation_count()-combined0<<" PAIR_B_ALLOCATIONS="<<c.b_pair_derivative_allocation_count()-pair0<<" ZERO_REPEAT_H2D="<<(zero?"PASS":"FAIL")<<'\n';return e<=tol&&decomp==0.&&sym<=1e-9&&repeat&&zero&&(h1-h0)==0&&(d1-d0)==9*sizeof(double)&&c.b_derivative_allocation_count()==combined0&&c.b_pair_derivative_allocation_count()==pair0+1;}
int main(){try{Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sig(2,2);double av[]={0,0,1,.2,.3,1.1},kv[]={0,0,1.5,1.5},zv[]={1.2,-.4,.7};std::copy(av,av+6,s.a.begin());std::copy(kv,kv+4,k.a.begin());std::copy(zv,zv+3,z.a.begin());for(double&v:x.a)v=1.;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sig(0,0)=.7;sig(1,1)=.4;sig(0,1)=sig(1,0)=.05;auto point=load("sync_gpu/tests/fixtures/sync_gpu/DELTA_THETA_POINT0_PARAM.txt"),smallh=load("sync_gpu/tests/fixtures/sync_gpu/DELTA_THETA_POINT0_HESSIAN.txt");GlobalParameters p{g,mu,sig,point(0,0),point(1,0),point(2,0)};bool ok=check("STREAM_THETA_HESSIAN_N=3",{s,z,x},k,p,smallh,1e-9);const fs::path f="sync_gpu/tests/fixtures/figure1_reference";GlobalParameters p100{load(f/"p_initial_gamma_new.txt"),load(f/"p_initial_global_mu.txt"),load(f/"p_initial_global_sigma.txt"),.25,1.,.11};ok=check("STREAM_THETA_HESSIAN_N=100",w100(100),load(f/"knots.txt"),p100,load(f/"p_initial_worker_0_hessian.txt"),1e-8)&&ok;std::cout<<"STREAMED_THETA_HESSIAN_PYTHON_AUTOGRAD_PARITY="<<(ok?"PASS":"FAIL")<<'\n';return ok?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
